from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")

        # Rule 3: a patient can have at most one upcoming appointment
        for appt in self._appointments.values():
            if appt["patient"] == patient and appt["active"] and appt["start"] >= now:
                raise ValueError(
                    "Patient already has an upcoming appointment."
                )

        # Rule 1 & 5: no overlap for the same doctor (touching is fine)
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not appt["active"]:
                continue
            if start < appt["end"] and appt["start"] < end:
                raise ValueError(
                    "Appointment overlaps with an existing one for this doctor."
                )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "id": appt_id,
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "active": True,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None or not appt["active"]:
            raise ValueError("Unknown or already-cancelled appointment.")

        # Rule 4: if cancelling < 24h before start, slot stays blocked.
        # The appointment is cancelled (no longer an upcoming appointment for
        # the patient and no longer counts for rule 3), but the slot must
        # remain blocked for the doctor.
        if appt["start"] - now < timedelta(hours=24):
            # Keep the time blocked by leaving a "ghost" booking that is
            # inactive for patient purposes but still blocks the doctor.
            appt["active"] = False
            appt["blocks_slot"] = True
        else:
            appt["active"] = False
            appt["blocks_slot"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            blocked = appt.get("active", False) or appt.get("blocks_slot", False)
            if not blocked:
                continue
            if start < appt["end"] and appt["start"] < end:
                return False
        return True
